  /** Everyone's due-total added up, skipping those with none. */
  protected readonly dueTotal = computed(() =>
    money([...this.dueByPerson().values()].reduce<number>((sum, due) => sum + (due ?? 0), 0)),
  );
  /** Each person's overdue claims that count: how many, and their dues added up in whole cents (none counting as 0). */
  private readonly overdueByPerson = computed(() => {
    const sheet = this.sheets.current();
    const dueTerms = sheet ?? DEFAULT_DUE_TERMS;
    const byPerson = new Map<number, Overdue>();
    for (const p of this.people()) {
      const overdue = sheet
        ? this.claimsOf(p.id).filter((c) => countsWithHolds(p.holds)(c) && isOverdue(c, sheet.today))
        : NO_CLAIMS;
      byPerson.set(p.id, {
        count: overdue.length,
        cents: overdue.reduce((sum, c) => sum + (this.claimDue(p, c, dueTerms) ?? 0), 0),
      });
    }
    return byPerson;
  });
  /** Everyone's overdue claims added up. */
  protected readonly overdueTotals = computed(() =>
    [...this.overdueByPerson().values()].reduce<Overdue>(
      (sum, o) => ({ count: sum.count + o.count, cents: sum.cents + o.cents }),
      NO_OVERDUE,
    ),
  );
  /** Each period's due-total, by period id: the dues of the claims that count whose date falls in it;
   *  a closed period keeps the total fixed when it was closed. */
  protected readonly dueByPeriod = computed(() => {
    counts(c) &&
    (c.stated ||
      (c.status !== 'OPEN' && c.status !== 'PENDING') ||
      !holds.some((h) => h.from <= c.date && (h.to === null || c.date <= h.to)));
}

/** The date (yyyy-mm-dd) that decides how a claim's live figures round: its own, or for a correction the date
 *  of the claim of the same person it corrects, found among that person's claims. */
export function roundingDate(
  c: Pick<ClaimView, 'date' | 'corrects'>,
  theirs: readonly Pick<ClaimView, 'date' | 'number'>[],
): string {
  if (c.corrects === null) return c.date;
  return theirs.find((o) => o.number === c.corrects)?.date ?? c.date;
}

/** Whether a claim is overdue on the sheet's today: OPEN or PENDING and due by a day before it. */
export function isOverdue(c: Pick<ClaimView, 'dueBy' | 'status'>, today: string): boolean {
  return (c.status === 'OPEN' || c.status === 'PENDING') && c.dueBy < today;
}

/** A claim as the form submits it: a blank date takes the sheet's today. A negative amount is a correction,
 *  which names in `corrects` the number of the claim it corrects. */
export interface ClaimForm {
  amount: string;
  date: string | null;
  note: string;
  corrects: string | null;
}

/** What a quick-add made: the person the claim is for, whether they were added by it, and the claim. */
export interface QuickAddView {
  person: PersonView;
  personAdded: boolean;
  claim: ClaimView;
}

/** What a bulk open did: how many it opened and refused, and the claims it opened. */
export interface BulkOpenView {
  opened: number;
  refused: number;
